const BUILD_STEPS=[{"n": "1", "icon": "🎯", "title": "Choose the Beaufighter role before buying extras", "text": "Start by deciding whether the model is a Mk.VI night fighter, a Coastal Command TF.X strike aircraft, or a Far East/SEAC attack aircraft. This controls the nose/radar fit, weapons, colours, markings and weathering. Do not build a generic Beaufighter and add rockets or radar afterwards without a dated photo or reliable profile.", "products": [{"label": "Open Tamiya 61053 Mk.VI", "url": "https://www.tamiya.com/english/products/61053/index.html"}, {"label": "Open Tamiya 61067 TF.Mk.X", "url": "https://www.themodelcentre.com/61067-tamiya-1-48-scale-bristol-beaufighter-tf-mk-x"}, {"label": "Open Airfix A04019A TF.X", "url": "https://uk.airfix.com/products/bristol-beaufighter-tfx-a04019a"}]}, {"n": "2", "icon": "🪑", "title": "Build the cockpit and observer/radar operator area as a crewed aircraft", "text": "Unlike the Spitfire page, the Beaufighter story is not a single-seat ace cockpit. Paint RAF Interior Grey-Green, keep the instrument panels dark, add harnesses, and make the observer/radar operator position look occupied by equipment rather than empty space. On night fighters, the radar installation and crew workflow are the modelling hook.", "products": [{"label": "Open Eduard Mk.VI LööKplus", "url": "https://www.eduard.com/eduard/brassin/aircraft/1-48/beaufighter-mk-vi-l%C3%B6%C3%B6kplus-1-48.html"}, {"label": "Open Eduard Mk.X LööKplus", "url": "https://www.eduard.com/eduard/brassin/aircraft/1-48/beaufighter-mk-x-l%C3%B6%C3%B6kplus-1-48.html"}, {"label": "Open Red Fox TF.X cockpit", "url": "https://www.scalemodelshop.co.uk/1-48-bristol-beaufighter-tf-mk-x-for-tamiya-kit-red-fox-studio-qs-48064-p20955/"}]}, {"n": "3", "icon": "🛞", "title": "Dry-fit nacelles, wings and undercarriage before paint", "text": "The Beaufighter is dominated by its Hercules nacelles and heavy undercarriage. Test the nacelle joins, wing roots and gear alignment early. A poor stance ruins the model faster than a small cockpit error. Resin or weighted wheels are worthwhile if the aircraft will sit on a hardstand or coastal dispersal base.", "products": [{"label": "Open Eduard Mk.VI wheels", "url": "https://www.eduard.com/eduard/brassin/aircraft/1-48/beaufighter-mk-vi-wheels-1-48.html"}, {"label": "Open Eduard Mk.X wheels", "url": "https://www.eduard.com/eduard/brassin/aircraft/1-48/beaufighter-mk-x-wheels-1-48.html"}]}, {"n": "4", "icon": "📡", "title": "Match aerials and weapons to one dated subject", "text": "AI radar aerials, rockets, torpedo gear and cannon fit must match the exact aircraft role. A 604 Squadron night fighter, a North Coates rocket aircraft and a Dallachy TF.X should not share the same stores and aerial fit. Fit fragile aerials late and use a jig or ruler to keep them symmetrical.", "products": [{"label": "Open Eduard Mk.VI TFace", "url": "https://www.eduard.com/eduard/masks/aircraft/1-48/beaufighter-mk-vi-tface-1-48.html"}, {"label": "Open Eduard Mk.X TFace", "url": "https://www.eduard.com/eduard/masks/aircraft/1-48/beaufighter-mk-x-tface-1-48.html"}]}, {"n": "5", "icon": "🎨", "title": "Paint by theatre, not by aircraft name alone", "text": "Night fighters need scale-black treatment: very dark grey, satin panels and rubbed edges, not dead black. Coastal Command aircraft need Extra Dark Sea Grey and Sky with salt fading, oil streaks and weathered walkways. SEAC aircraft need faded RAF colours, dust, humidity and toned-down markings.", "products": [{"label": "Open Valiant Wings Beaufighter book", "url": "https://www.valiant-wings.co.uk/airframe--miniature-no26-6032-p.asp"}]}, {"n": "6", "icon": "🧴", "title": "Weather the Hercules engines and strike finish last", "text": "Add staining in layers: exhaust grey-brown behind the Hercules engines, oil along nacelles, dirty access panels, tyre dust and salt streaking for Coastal Command. Keep chipping restrained: the Beaufighter should look hard-worked and heavy, not like a silver-edged toy.", "products": [{"label": "Open RAF Museum Beaufighter reference", "url": "https://www.rafmuseum.org.uk/research/collections/bristol-beaufighter-tf-x/"}]}];

