// ═══ COMPARE ═══
function initCompare(){
  const opts=SQ.map(s=>`<option value="${s.num}">No.${s.num} Sqn — ${s.base}</option>`).join('');
  document.getElementById('cmp-a').innerHTML=opts;
  document.getElementById('cmp-b').innerHTML=opts;
  document.getElementById('cmp-b').value='92';
  renderCompare();
}
function renderCompare(){
  const na=document.getElementById('cmp-a').value,nb=document.getElementById('cmp-b').value;
  const a=SQ.find(s=>s.num===na),b=SQ.find(s=>s.num===nb);if(!a||!b)return;
  const maxK=Math.max(...SQ.map(s=>s.kills)),maxS=Math.max(...SQ.map(s=>s.sorties)),maxKR=Math.max(...SQ.map(s=>s.kills/s.sorties)),maxP=Math.max(...SQ.map(s=>s.pilots.length));
  function norm(v,m){return Math.min(100,Math.round(v/m*100));}
  const axes=[{label:"Claims",a:norm(a.kills,maxK),b:norm(b.kills,maxK)},{label:"Sorties",a:norm(a.sorties,maxS),b:norm(b.sorties,maxS)},{label:"Kill Rate",a:norm(a.kills/a.sorties,maxKR),b:norm(b.kills/b.sorties,maxKR)},{label:"Pilots",a:norm(a.pilots.length,maxP),b:norm(b.pilots.length,maxP)},{label:"Group",a:a.group==='11'?100:a.group==='10'?75:50,b:b.group==='11'?100:b.group==='10'?75:50}];
  const N=axes.length,cx=200,cy=200,r=150,aS=(Math.PI*2)/N;
  function pp(i,val,rad){const angle=i*aS-Math.PI/2;const d=rad*val/100;return[cx+d*Math.cos(angle),cy+d*Math.sin(angle)];}
  let wr='';[20,40,60,80,100].forEach(p=>{wr+=`<polygon points="${axes.map((_,i)=>pp(i,p,r).join(',')).join(' ')}" fill="none" stroke="rgba(255,255,255,.12)" stroke-width="${p===100?1.5:.8}"/>`;});
  let al='',lab='';axes.forEach((ax,i)=>{const[x2,y2]=pp(i,100,r);al+=`<line x1="${cx}" y1="${cy}" x2="${x2}" y2="${y2}" stroke="rgba(255,255,255,.15)" stroke-width="1"/>`;const[lx,ly]=pp(i,100,r+22);lab+=`<text x="${lx}" y="${ly}" text-anchor="middle" dominant-baseline="middle" style="font-family:sans-serif;font-size:11px;fill:rgba(255,255,255,.7)">${ax.label.toUpperCase()}</text>`;});
  const pA=axes.map((_,i)=>pp(i,axes[i].a,r).join(',')).join(' ');
  const pB=axes.map((_,i)=>pp(i,axes[i].b,r).join(',')).join(' ');
  let dA='',dB='';axes.forEach((ax,i)=>{const[x1,y1]=pp(i,ax.a,r);const[x2,y2]=pp(i,ax.b,r);dA+=`<circle cx="${x1}" cy="${y1}" r="4" fill="rgba(74,127,165,.9)" stroke="#fff" stroke-width="1.5"/>`;dB+=`<circle cx="${x2}" cy="${y2}" r="4" fill="rgba(184,144,42,.9)" stroke="#fff" stroke-width="1.5"/>`;});
  const kr_a=(a.kills/a.sorties).toFixed(2),kr_b=(b.kills/b.sorties).toFixed(2);
  const top3_a=a.pilots.slice().sort((x,y)=>y.k-x.k).slice(0,3).map(p=>p.n.split(' ').pop()+'('+p.k+')').join(', ');
  const top3_b=b.pilots.slice().sort((x,y)=>y.k-x.k).slice(0,3).map(p=>p.n.split(' ').pop()+'('+p.k+')').join(', ');
  const row=(label,va,vb,col)=>'<tr><td style="color:rgba(255,255,255,.42);padding:2px 0;font-size:13px">'+label+'</td><td style="color:'+(col||'#fff')+';text-align:right;font-size:13px">'+va+'</td><td style="color:'+(col||'#fff')+';text-align:right;font-size:13px">'+vb+'</td></tr>';
  document.getElementById('compare-output').innerHTML=`<div style="background:rgba(21,39,68,.8);border:2px solid rgba(255,255,255,.1);border-radius:1px;padding:1rem"><div style="display:flex;justify-content:center;gap:2rem;margin-bottom:.75rem;flex-wrap:wrap"><div style="display:flex;align-items:center;gap:8px"><div style="width:16px;height:3px;background:rgba(74,127,165,.9);border-radius:1px"></div><span style="font-family:'Special Elite',cursive;font-size:14px;color:#7ab8e8">No.${a.num} Sqn — ${a.base}</span></div><div style="display:flex;align-items:center;gap:8px"><div style="width:16px;height:3px;background:rgba(184,144,42,.9);border-radius:1px"></div><span style="font-family:'Special Elite',cursive;font-size:14px;color:var(--brass2)">No.${b.num} Sqn — ${b.base}</span></div></div><div style="display:flex;justify-content:center"><svg viewBox="0 0 400 430" style="width:100%;max-width:420px"><g transform="translate(0,10)">${wr}${al}<polygon points="${pA}" fill="rgba(74,127,165,.2)" stroke="rgba(74,127,165,.9)" stroke-width="2" stroke-linejoin="round"/><polygon points="${pB}" fill="rgba(184,144,42,.15)" stroke="rgba(184,144,42,.9)" stroke-width="2" stroke-linejoin="round" stroke-dasharray="6,3"/>${dA}${dB}${lab}</g></svg></div><div style="font-family:'Courier Prime',monospace;font-size:11px;color:rgba(255,255,255,.4);margin-top:.5rem">Values normalised to 0–100 across the selected Beaufighter units. Solid = No.${a.num}, dashed = No.${b.num}.</div></div>`+
  '<div style="margin-top:1.2rem;background:rgba(0,0,0,.3);border:1px solid rgba(255,255,255,.1);border-radius:3px;padding:1rem;overflow-x:auto"><table style="width:100%;border-collapse:collapse"><tr style="border-bottom:1px solid rgba(255,255,255,.08)"><th style="text-align:left;font-family:Oswald,sans-serif;font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:rgba(255,255,255,.3);padding-bottom:.5rem">Stat</th><th style="text-align:right;font-family:Oswald,sans-serif;font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--brass2);padding-bottom:.5rem">No.'+na+' — '+a.base+'</th><th style="text-align:right;font-family:Oswald,sans-serif;font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--raf-sky);padding-bottom:.5rem">No.'+nb+' — '+b.base+'</th></tr>'+row('Group',a.group+' Group',b.group+' Group')+row('Nationality',a.nat||'British',b.nat||'British')+row('Marks',a.marks||'Mk.I',b.marks||'Mk.I')+row('First action',a.firstOp||'Jul 1940',b.firstOp||'Jul 1940')+row('Last action',a.lastOp||'Oct 1940',b.lastOp||'Oct 1940')+row('Claims',a.kills,b.kills,'var(--brass2)')+row('Sorties',a.sorties,b.sorties)+row('Kill rate/sortie',kr_a,kr_b)+row('Aircraft lost',a.losses||'—',b.losses||'—','rgba(255,120,100,.8)')+row('Named pilots',a.pilots.length,b.pilots.length)+row('Top scorers',top3_a,top3_b)+'</table></div>';
}

// ═══ TIMELINE ═══
const TL_START=new Date('1940-07-10');
function getPhase(day){return PHASES.find(p=>day>=p.start&&day<=p.end)||PHASES[3];}
function dayToDate(d){const dt=new Date(TL_START);dt.setDate(dt.getDate()+d);return dt.toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'});}
function getSqStatus(num,day){const periods=TL[num]||[];const p=periods.find(x=>day>=x.s&&day<=x.e);return p?p.st:'rest';}
function updateTimeline(val){
  const day=parseInt(val);
  const phase=getPhase(day);
  const exactEvent=EVENTS.find(e=>e[0]===day);
  const prev=EVENTS.filter(e=>e[0]<=day).pop();
  const next=EVENTS.find(e=>e[0]>day);
  const stColors={front:'#9ab840',reserve:'#d4a83a',rest:'rgba(255,255,255,.35)'};
  const stLabels={front:'Front line',reserve:'Reserve',rest:'Resting'};
  const stBgs={front:'rgba(100,130,30,.18)',reserve:'rgba(184,144,42,.13)',rest:'rgba(255,255,255,.04)'};
  document.getElementById('tl-date').textContent=dayToDate(day);
  let eventHtml='';
  if(exactEvent){eventHtml=`<div style="background:${phase.colour};color:#e8dfc0;border-radius:1px;padding:.75rem 1rem;margin:.75rem 0;border-left:4px solid var(--gold3)"><div style="font-family:'Special Elite',cursive;font-size:15px;margin-bottom:.3rem">${exactEvent[1]}</div><div style="font-family:'Courier Prime',monospace;font-size:13px">${exactEvent[2]}</div>${exactEvent[3]>0?`<div style="margin-top:.4rem;font-size:11px;opacity:.8">RAF losses: <b>${exactEvent[3]}</b> &nbsp;·&nbsp; Luftwaffe: <b>${exactEvent[4]}</b></div>`:''}</div>`;}
  else if(prev){eventHtml=`<div style="background:rgba(21,39,68,.7);border-radius:1px;padding:.6rem 1rem;margin:.75rem 0;font-family:'Courier Prime',monospace;font-size:11px;color:var(--brass2);border-left:3px solid var(--khaki)">Last event: <b style="color:rgba(255,255,255,.85)">${prev[1]}</b>${next?`<br>Next: <b style="color:rgba(255,255,255,.85)">${next[1]}</b> (${dayToDate(next[0])})`:''}</div>`;}
  document.getElementById('tl-event-detail').innerHTML=`<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:.75rem"><div style="background:${phase.colour};color:#e8dfc0;padding:.6rem .9rem;border-radius:1px"><div style="font-family:'Oswald',sans-serif;font-size:12px;letter-spacing:.12em;text-transform:uppercase;opacity:.7;margin-bottom:3px">Current Phase</div><div style="font-family:'Special Elite',cursive;font-size:13px">${phase.name}</div><div style="font-family:'Courier Prime',monospace;font-size:13px;margin-top:4px;opacity:.8;line-height:1.4">${phase.desc}</div></div><div style="background:rgba(21,39,68,.7);padding:.6rem .9rem;border-radius:1px;border:1px solid rgba(255,255,255,.1)"><div style="font-family:'Oswald',sans-serif;font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:var(--brass2);margin-bottom:3px">Day ${day+1} of 114</div><div style="font-family:'Courier Prime',monospace;font-size:12px;color:rgba(255,255,255,.85)"><span style="color:#9ab840;font-weight:700">${SQ.filter(s=>getSqStatus(s.num,day)==='front').length}</span> sqns front &nbsp;<span style="color:var(--gold);font-weight:700">${SQ.filter(s=>getSqStatus(s.num,day)==='reserve').length}</span> reserve &nbsp;<span style="color:var(--brass2);font-weight:700">${SQ.filter(s=>getSqStatus(s.num,day)==='rest').length}</span> resting</div></div></div>${eventHtml}`;
  document.getElementById('tl-sqns').innerHTML=SQ.map(sq=>{const st=getSqStatus(sq.num,day);return`<div class="tl-sqn ${st==='front'?'active-tl':''}" style="border-left-color:${stColors[st]};background:${stBgs[st]}"><div class="tl-sqn-num" style="color:${stColors[st]}">No.${sq.num} Sqn</div><div class="tl-sqn-status">${sq.base}</div><div style="font-size:13px;font-family:'Oswald',sans-serif;letter-spacing:.05em;color:${stColors[st]};margin-top:2px;text-transform:uppercase">${stLabels[st]}</div></div>`;}).join('');
}

// ═══ MAP ═══
const GROUP_COLOURS={night:'#4a7fa5',coastal:'#7bb0a0',med:'#c28d4a',fareast:'#b8902a'};
const JITTER={
  'hornchurch':{dx:16,dy:0,lx:10,ly:-6,la:'start'},
  'biggin':{dx:8,dy:8,lx:10,ly:4,la:'start'},
  'kenley':{dx:-8,dy:8,lx:-10,ly:4,la:'end'},
  'westhampnett':{dx:0,dy:0,lx:8,ly:-8,la:'start'},
  'drem':{dx:-8,dy:-4,lx:-10,ly:-4,la:'end'},
  'turnhouse':{dx:8,dy:4,lx:10,ly:4,la:'start'},
};

let mapRendered=false;
let leafletMap=null;
let leafletMarkers={};
let leafletZones={};
let selectedStationId=null;

function xyToLatLng(st){
  // Prefer verified WGS84 coordinates where supplied. The old x/y values remain as a fallback only.
  if(typeof st.lat === 'number' && typeof st.lon === 'number') return [st.lat, st.lon];
  if(typeof st.lat === 'number' && typeof st.lng === 'number') return [st.lat, st.lng];
  const lon = -7 + ((st.x - 25) / 470) * 9.5;
  const lat = 59 - ((st.y - 20) / 660) * 9.5;
  return [lat, lon];
}
function mapGroupLabel(group){
  return group==='night'?'Night Fighter':group==='coastal'?'Coastal Strike':group==='med'?'Mediterranean / Desert':group==='fareast'?'Far East / RAAF Pacific':'All Theatres';
}
function renderMap(){
  const mapEl=document.getElementById('leaflet-map');
  if(!mapEl) return;
  if(mapRendered){ setTimeout(()=>leafletMap && leafletMap.invalidateSize(), 80); return; }
  if(typeof L==='undefined'){
    mapEl.innerHTML = `<div style="padding:2rem;color:rgba(255,255,255,.65);font-family:'Oswald',sans-serif;letter-spacing:.08em;text-transform:uppercase">Map library loading…</div>`;
    setTimeout(renderMap,250); return;
  }
  mapRendered=true;
  leafletMap = L.map('leaflet-map', {
    zoomControl:true,
    attributionControl:true,
    scrollWheelZoom:false,
    maxBounds:[[49.2,-8.8],[58.8,4.0]],
    maxBoundsViscosity:.65
  }).setView([53.0,-1.6],5);

  L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', {
    attribution:'&copy; OpenStreetMap &copy; CARTO',
    subdomains:'abcd', maxZoom:10, minZoom:4
  }).addTo(leafletMap);

  const zones = {
    '10': [[50.0,-6.2],[50.5,-5.4],[51.0,-4.4],[51.4,-3.2],[51.7,-2.0],[51.7,-1.0],[50.8,-1.2],[50.0,-2.2],[49.9,-4.2]],
    '11': [[50.3,-1.8],[50.6,-0.8],[51.0,-0.2],[51.6,0.5],[52.1,1.6],[52.0,1.9],[51.3,1.8],[50.6,1.4],[50.2,0.4],[50.1,-0.6]],
    '12': [[51.6,-3.0],[52.1,-2.2],[52.8,-1.6],[53.5,-0.4],[53.7,1.2],[53.3,1.8],[52.4,1.8],[51.8,1.4],[51.6,0.0]],
    '13': [[54.2,-4.2],[55.0,-4.0],[55.9,-3.2],[56.8,-2.0],[57.4,-0.8],[57.0,0.6],[56.0,0.2],[55.0,-0.6],[54.2,-1.8]]
  };
  leafletZones={};
  Object.entries(zones).forEach(([key,coords])=>{
    leafletZones[key]=L.polygon(coords,{color:GROUP_COLOURS[key],weight:1,opacity:.34,fillColor:GROUP_COLOURS[key],fillOpacity:.08,interactive:false}).addTo(leafletMap);
  });

  leafletMarkers={};
  STATIONS.forEach(st=>{
    const [lat,lng] = xyToLatLng(st);
    st._lat = lat; st._lng = lng;
    const col = GROUP_COLOURS[st.group] || '#999';
    const icon=L.divIcon({className:'',html:`<div class="raf-leaflet-marker" data-id="${st.id}" style="background:${col}"></div>`,iconSize:[18,18],iconAnchor:[9,9]});
    const marker=L.marker([lat,lng],{icon}).addTo(leafletMap);
    marker._rafStation = st;
    marker.on('click',()=>showMapStation(st));
    marker.bindTooltip(`<span class="raf-leaflet-label">${st.name}</span>`,{permanent:false,direction:'top',offset:[0,-10],opacity:.96,className:''});
    leafletMarkers[st.id]=marker;
  });
  leafletMap.fitBounds([[49.5,-7.5],[57.9,2.5]], {padding:[16,16]});
  setTimeout(()=>leafletMap.invalidateSize(),100);
  showMapIntro();
}

function rafMapTypeLabel(st){
  const info=(st.info||'').toLowerCase();
  if(info.includes('coastal')||info.includes('strike')||info.includes('dallachy')||info.includes('banff')) return 'Coastal strike base';
  if(info.includes('night')||info.includes('radar')||info.includes('blitz')) return 'Night-fighter base';
  if(info.includes('seac')||info.includes('burma')||info.includes('far east')||info.includes('india')) return 'Far East operating base';
  return 'Beaufighter operating base';
}
function rafCrewContextText(sq){
  if(!sq || !sq.pilots || !sq.pilots.length) return 'Crew and role notes in the unit card';
  const lead = sq.pilots[0];
  const role = (sq.ops||'').toLowerCase().includes('coastal') ? 'strike crew context' : (sq.ops||'').toLowerCase().includes('night') ? 'night-fighter crew context' : 'unit crew context';
  return `${lead.n} · ${role} · ${lead.fate || 'service details'}`;
}
function rafStationModellingCue(st){
  const info = (st.info || '').toLowerCase();
  if(info.includes('chalk')) return 'Pale chalk or flint dust on tyres, undercarriage legs and lower wing roots. Keep exhaust and gun staining visible but avoid over-mudding.';
  if(info.includes('clay')) return 'Brown-grey clay staining around wheels, tailwheel and undersides. Add darker damp mud on dispersal-heavy aircraft.';
  if(info.includes('red clay')) return 'Warm reddish-brown dust and mud around undercarriage and wing-root walkways; good contrast against Sky undersides.';
  if(info.includes('gravel')) return 'Light grey-brown dust on tyres and lower surfaces. Use restrained staining; aircraft often look dusty rather than muddy.';
  if(info.includes('coastal') || info.includes('naval') || info.includes('portland')) return 'Coastal grime, salt air fading, pale dust and stronger exhaust staining from frequent scrambles.';
  if(st.group === '13') return 'Northern station conditions: damp grass, cooler tones, restrained dust and slightly dirtier tyres.';
  if(st.group === '10') return 'West Country conditions: pale dust on hard summer days, heavier mud after rain and strong exhaust staining from repeated patrols.';
  return 'Beaufighter field wear: Hercules exhaust staining, nacelle oil streaks, crew access wear and theatre-specific fading or dust.';
}
function rafOpenMapUnit(num){
  const clean = String(num).replace(' fwd','');
  const sq = SQ.find(s => s.num === clean);
  if(!sq) return;
  document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('active'));
  const sqPanel = document.getElementById('tab-squadrons');
  if(sqPanel) sqPanel.classList.add('active');
  document.querySelectorAll('.nav-tab').forEach(t => t.classList.remove('active'));
  const sqTab = [...document.querySelectorAll('.nav-tab')].find(t => (t.getAttribute('onclick')||'').includes("'squadrons'"));
  if(sqTab) sqTab.classList.add('active');
  const bar = document.getElementById('sqn-bar');
  if(bar) bar.style.display = 'flex';
  if(typeof activeTab !== 'undefined') activeTab = 'squadrons';
  if(typeof activeFilter !== 'undefined') activeFilter = 'all';
  document.querySelectorAll('.fb.gf').forEach(b => b.classList.remove('on'));
  const allBtn = [...document.querySelectorAll('.fb.gf')].find(b => (b.getAttribute('onclick')||'').includes("'all'"));
  if(allBtn) allBtn.classList.add('on');
  if(typeof renderGrid === 'function') renderGrid();
  setTimeout(() => {
    if(typeof selectSq === 'function') selectSq(clean);
    const card = document.getElementById('card-' + clean);
    if(card) card.scrollIntoView({behavior:'smooth', block:'center'});
  }, 40);
}
function showMapIntro(){
  const box=document.getElementById('map-sqn-list');
  if(!box) return;
  const stationCount = STATIONS.length;
  const linkedUnits = [...new Set(STATIONS.flatMap(st => (st.sqns||[]).map(n => String(n).replace(' fwd',''))).filter(n => SQ.find(s => s.num === n)))];
  const byGroup = ['11','10','12','13'].map(g => `${mapGroupLabel(g)}: ${STATIONS.filter(s=>s.group===g).length}`).join(' · ');
  box.innerHTML = `
    <div style="font-family:'Special Elite',cursive;font-size:1.18rem;color:#fff;margin-bottom:.35rem">Beaufighter operations map</div>
    <div style="font-family:'Oswald',sans-serif;font-size:11px;letter-spacing:.13em;text-transform:uppercase;color:var(--brass2);margin-bottom:.75rem">Clickable bases → linked unit cards</div>
    <p style="font-size:14px;color:rgba(255,255,255,.68);line-height:1.65">Hover a marker to reveal the base name, or click it to open the base summary and linked Beaufighter unit cards. The linked unit card contains operations, markings, paint and modelling notes.</p>
    <div style="margin-top:.75rem;font-family:'Oswald',sans-serif;font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:rgba(255,255,255,.45)">${stationCount} base markers · ${linkedUnits.length} linked unit cards</div>
    <div style="margin-top:.45rem;font-family:'Oswald',sans-serif;font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:rgba(255,255,255,.38)">${byGroup}</div>`;
}
function showMapStation(stOrId){
  const st = typeof stOrId === 'string' ? STATIONS.find(s => s.id === stOrId) : stOrId;
  if(!st) return;
  const groupCol = GROUP_COLOURS[st.group] || '#666';
  const typeLabel = rafMapTypeLabel(st);
  const box = document.getElementById('map-sqn-list');
  if(!box) return;
  selectedStationId = st.id;
  Object.entries(leafletMarkers || {}).forEach(([mid,m]) => {
    const el = m.getElement && m.getElement();
    if(el){ const dot = el.querySelector('.raf-leaflet-marker'); if(dot) dot.classList.toggle('selected', mid === st.id); }
  });
  if(leafletMap && leafletMarkers[st.id]) leafletMap.panTo([st._lat, st._lng], {animate:true, duration:.45});

  const unitCards = (st.sqns || []).map(n => {
    const clean = String(n).replace(' fwd','');
    const sq = SQ.find(s => s.num === clean);
    if(sq){
      return `<button class="map-sqn-chip" onclick="rafOpenMapUnit('${sq.num.replace(/'/g,"\\'")}')" style="display:block;width:100%;text-align:left;border-left:3px solid var(--brass);padding:.65rem .8rem;margin-bottom:.45rem;background:rgba(255,255,255,.045);cursor:pointer">
        <b>No.${n} Sqn</b>${String(n).includes('fwd') ? ' <span style="color:rgba(255,255,255,.45)">(fwd dispersal)</span>' : ''}
        <div style="font-family:'Oswald',sans-serif;font-size:11px;letter-spacing:.05em;text-transform:uppercase;color:rgba(255,255,255,.55);margin-top:2px">${sq.marks || ''} · ${sq.base || st.name} · ${sq.pilots ? sq.pilots.length : 0} pilots</div>
        <div style="font-size:12px;color:rgba(255,255,255,.76);line-height:1.45;margin-top:4px">Crew focus: ${rafCrewContextText(sq)}<br>Open unit card for role, markings, stores and modelling notes →</div>
      </button>`;
    }
    return `<div class="map-sqn-chip" style="border-left:3px solid rgba(255,255,255,.25);opacity:.72;cursor:default;padding:.65rem .8rem;margin-bottom:.45rem">
      <b>No.${n} Sqn</b>
      <div style="font-size:12px;color:rgba(255,255,255,.65);line-height:1.45;margin-top:4px">Context unit — no linked squadron card on this page.</div>
    </div>`;
  }).join('');

  box.innerHTML = `
    <div style="margin-bottom:.85rem;padding-bottom:.85rem;border-bottom:2px solid rgba(255,255,255,.12)">
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:.45rem;flex-wrap:wrap">
        <div style="width:12px;height:12px;border-radius:50%;background:${groupCol};flex-shrink:0"></div>
        <span style="font-family:'Special Elite',cursive;font-size:18px;color:rgba(255,255,255,.92)">${st.name}</span>
      </div>
      <div style="font-family:'Oswald',sans-serif;font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--brass2);margin-bottom:.7rem">${st.group} Group · ${typeLabel}</div>
      ${st.info ? `<div style="font-family:'Source Serif 4',Georgia,serif;font-size:14px;color:rgba(255,255,255,.82);line-height:1.65;margin-bottom:.65rem">${st.info}</div>` : ''}
      <div style="font-size:13px;color:rgba(255,255,255,.72);line-height:1.6"><strong style="color:var(--brass2)">Modelling cue:</strong> ${rafStationModellingCue(st)}</div>
    </div>
    <div style="font-family:'Oswald',sans-serif;font-size:13px;letter-spacing:.08em;text-transform:uppercase;color:var(--brass2);margin-bottom:.5rem">Linked Beaufighter unit cards</div>
    ${unitCards || '<div class="map-sqn-chip" style="color:var(--brass2)">No squadron data</div>'}
  `;
}
function filterMapGroup(group,btn){
  renderMap();
  document.querySelectorAll('.map-filter-btn').forEach(b=>b.classList.remove('on'));
  if(btn) btn.classList.add('on');
  Object.entries(leafletZones || {}).forEach(([key,z]) => {
    if(!z) return;
    z.setStyle({fillOpacity:(group==='all'||key===group)?.12:.025, opacity:(group==='all'||key===group)?.42:.16});
  });
  Object.entries(leafletMarkers || {}).forEach(([id,marker]) => {
    const st = marker._rafStation;
    const show = group==='all' || st.group===group;
    if(show){ if(leafletMap && !leafletMap.hasLayer(marker)) marker.addTo(leafletMap); }
    else { if(leafletMap && leafletMap.hasLayer(marker)) leafletMap.removeLayer(marker); }
    const el = marker.getElement && marker.getElement();
    if(el){ const dot = el.querySelector('.raf-leaflet-marker'); if(dot) dot.classList.remove('selected'); }
  });
  selectedStationId=null;
  const shown = STATIONS.filter(st => group==='all' || st.group===group);
  if(leafletMap && shown.length){
    const bounds=L.latLngBounds(shown.map(st => [st._lat, st._lng]));
    leafletMap.fitBounds(bounds.pad(.35), {padding:[20,20], maxZoom: group==='all' ? 6 : 7});
  }
  const box=document.getElementById('map-sqn-list');
  if(box){
    box.innerHTML = `
      <div style="font-family:'Special Elite',cursive;font-size:1.18rem;color:#fff;margin-bottom:.35rem">${group==='all' ? 'All Beaufighter bases' : mapGroupLabel(group)}</div>
      <div style="font-family:'Oswald',sans-serif;font-size:11px;letter-spacing:.13em;text-transform:uppercase;color:var(--brass2);margin-bottom:.75rem">${shown.length} marker${shown.length===1?'':'s'} shown</div>
      <p style="font-size:14px;color:rgba(255,255,255,.68);line-height:1.65">Click a visible marker or choose a station below. Linked units open the matching Beaufighter card with crew context, markings, stores and modelling notes.</p>
      <div style="max-height:230px;overflow:auto;padding-right:.2rem;margin-top:.7rem">
        ${shown.map(st => `<div class="map-sqn-chip" onclick="showMapStation('${st.id}')" style="margin-top:.45rem;cursor:pointer"><b>${st.name}</b><div style="font-size:11px;color:rgba(255,255,255,.65)">${(st.sqns||[]).join(' · ')} · ${rafMapTypeLabel(st)}</div></div>`).join('')}
      </div>`;
  }
}


// ═══ SURVIVORS ═══
