  const now=new Date();const m=now.getMonth()+1,d=now.getDate();
  const md=(m<10?'0':'')+m+'-'+(d<10?'0':'')+d;
  const best=BOB_EVENTS.find(e=>e.md===md)||BOB_EVENTS[Math.floor(Math.random()*BOB_EVENTS.length)];
  const [bm,bd]=best.md.split('-');const date1940=new Date(1940,parseInt(bm)-1,parseInt(bd));
  el.innerHTML=`<div style="background:rgba(21,39,68,.8);border:2px solid var(--brass);border-radius:4px;overflow:hidden"><div style="background:rgba(0,0,0,.35);padding:.75rem 1.2rem;border-bottom:1px solid rgba(184,144,42,.3)"><div style="font-family:'Oswald',sans-serif;font-size:13px;letter-spacing:.15em;text-transform:uppercase;color:var(--brass);margin-bottom:.3rem">Beaufighter modelling focus</div><div style="font-family:'Special Elite',cursive;font-size:1.2rem;color:#fff">Night fighter · Coastal strike · Far East attack</div></div><div style="padding:1rem 1.2rem;font-size:17px;color:rgba(255,255,255,.85);line-height:1.75">Choose the Beaufighter role first. Night fighters need black finish and AI aerials; Coastal Command aircraft need strike stores and salt fading; Far East aircraft need SEAC markings, dust and sun fading.</div></div>`;
