const BEAU_STORIES = [{"name": "John Cunningham and C. F. Rawnsley", "unit": "604 Squadron", "aircraft": "Beaufighter Mk.IF", "tag": "Night fighter crew", "story": "The Beaufighter\u2019s early fame came from night fighting, and Cunningham\u2019s crew with radar operator C. F. Rawnsley shows why this aircraft should not be treated like a single-seat ace fighter. The kill was created by aircraft, radar, operator, pilot and ground control working together. For the page, this story justifies the crew-card approach and the focus on AI aerials, black finish, cockpit/radar-operator areas and heavy exhaust staining.", "model": "Build as a crewed weapon system: AI aerials aligned cleanly, black finish subtly varied, crew access wear around cockpit openings, and brown-grey Hercules staining swept back along the nacelles."}, {"name": "604 Squadron night defence", "unit": "604 Squadron", "aircraft": "Beaufighter Mk.IF", "tag": "UK night defence", "story": "604 Squadron is the classic Beaufighter night-fighter subject. The aircraft\u2019s size, radar fit and cannon armament made it a practical answer to the night Blitz. The modelling story is not colourful markings; it is restrained black finish, dull codes, aerial arrays and the functional look of an aircraft flown in darkness from damp British stations.", "model": "Use low-contrast weathering: rubbed black paint, exhaust staining, mud on tyres and subtle leading-edge wear rather than bright chipping everywhere."}, {"name": "Dallachy Strike Wing crews", "unit": "404 RCAF / 489 RNZAF", "aircraft": "Beaufighter TF.X", "tag": "Coastal Command strike", "story": "The Dallachy Strike Wing gives the Beaufighter its hardest late-war look. Crews flew low-level anti-shipping attacks from Scotland over cold seas and into heavy flak. The TF.X subjects need to feel like strike aircraft: rockets or torpedo gear, weathered Coastal Command finish, salt deposits and operational grime around the Hercules engines.", "model": "Pick a named unit before choosing stores. Add rocket rails or torpedo fit carefully, fade upper colours, and concentrate grime behind nacelles and along walkways."}, {"name": "No.455 Squadron RAAF", "unit": "455 Squadron RAAF", "aircraft": "Beaufighter TF.X", "tag": "Commonwealth strike wing", "story": "455 Squadron helps broaden the page beyond RAF-only wording. RAAF crews in Coastal Command Beaufighters are a strong modelling subject because the aircraft combine British colours and Commonwealth identity with strike-wing wear. They suit the site\u2019s aircraft reference approach: unit, theatre, markings and weathering all change the model.", "model": "Use Commonwealth crew captions, check UB codes carefully, and weather the aircraft as a hard-used maritime strike machine rather than a clean museum display."}, {"name": "Far East Beaufighter crews", "unit": "27 / 177 Squadrons", "aircraft": "Beaufighter Mk.VI / TF.X", "tag": "SEAC and Burma", "story": "In India and Burma the Beaufighter became a rugged attack aircraft operating from rough, hot, dusty strips. The aircraft\u2019s look changes completely from UK night fighter subjects: SEAC roundels, sun fading, dust, monsoon staining and chipped access areas become the visual story.", "model": "Use theatre-specific markings. Add dust to tyres and lower surfaces, fade upper camouflage, and avoid copying UK night-fighter colours onto SEAC aircraft."}, {"name": "Australian Mk.21 Beaufighters", "unit": "RAAF Pacific units", "aircraft": "Beaufighter Mk.21", "tag": "Pacific / RAAF", "story": "Australian-built Mk.21 Beaufighters extend the aircraft into Pacific modelling. These subjects are not just RAF aircraft with different decals: details, weapons fit, finish and theatre wear need checking. They are ideal for modellers who want red dust, sun-faded paint and Australian markings.", "model": "Check Mk.21 references before copying RAF TF.X details. Emphasise Pacific fading, dusty tyres, stained nacelles and RAAF-specific markings."}];
const BEAU_PHASES = [{"year": "1939", "title": "Development from the Beaufort", "role": "Prototype and production planning", "text": "The Beaufighter was developed from the Beaufort, combining a powerful twin-engine airframe with heavy forward armament. Early modelling focus: clean prototype/early-production lines, short-tail and early equipment details where relevant.", "colour": "rgba(74,127,165,.28)"}, {"year": "1940\u201341", "title": "First high-performance AI night fighter", "role": "RAF night defence", "text": "The Beaufighter becomes a serious night fighter with airborne interception radar and cannon armament. Modelling focus: overall Night finish, AI aerials, subdued RAF markings, black paint variation and heavy exhaust staining.", "colour": "rgba(74,127,165,.38)"}, {"year": "1942", "title": "Mediterranean and early strike expansion", "role": "Malta, North Africa and wider fighter-bomber work", "text": "Beaufighters move beyond UK night defence into overseas fighter-bomber and anti-shipping work. Modelling focus: theatre repainting, dust, sun fading, tropical operating wear and careful stores selection.", "colour": "rgba(184,144,42,.30)"}, {"year": "1943", "title": "Coastal Command strike aircraft", "role": "Rockets, torpedo and anti-shipping attacks", "text": "The TF.X becomes a major maritime strike aircraft. Modelling focus: Coastal Command camouflage, rockets or torpedo gear, salt fading, dirty nacelles and flak-worn hard-service finishes.", "colour": "rgba(123,176,160,.32)"}, {"year": "1944", "title": "Dallachy, Banff and Far East operations", "role": "Strike wings and SEAC attack aircraft", "text": "Late-war Beaufighters serve in dangerous low-level strike wings and in Far East attack roles. Modelling focus: unit codes, C/C1 or SEAC markings, rockets, battered leading edges, dust or salt depending theatre.", "colour": "rgba(120,160,90,.30)"}, {"year": "1945", "title": "Late-war and post-war transfer", "role": "Portuguese, Australian and survivor trails", "text": "Some Beaufighters move into post-war service or survive as museum/restoration references. Modelling focus: separate wartime schemes from museum finishes; use survivors for structure, not automatic paint accuracy.", "colour": "rgba(138,122,74,.32)"}, {"year": "Today", "title": "Rare survivor and restoration reference", "role": "Museum and modelling research", "text": "Complete Beaufighters are scarce, so modellers rely heavily on RD253, restoration photographs, archive film and unit histories. Modelling focus: triangulate survivor details with wartime photos and kit instructions.", "colour": "rgba(201,168,76,.22)"}];
function beauThumbCard(item){return `<a class="wa-ref-card" href="${item.url}" target="_blank" rel="noopener"><img src="${item.thumb}" alt="${item.title} thumbnail" loading="lazy" onerror="this.src='video-thumb-fallback.png'"/><div class="wa-ref-body"><div class="wa-ref-kicker">${item.type}</div><div class="wa-ref-title">${item.title}</div><div class="wa-ref-desc">${item.desc}</div><div class="wa-ref-link">${item.button} ↗</div></div></a>`}
function updateTimeline(val){const idx=Math.max(0,Math.min(BEAU_PHASES.length-1,parseInt(val||0,10)));const p=BEAU_PHASES[idx];const date=document.getElementById('tl-date');if(date)date.textContent=p.year+' — '+p.title;const detail=document.getElementById('tl-event-detail');if(detail)detail.innerHTML=`<div style="display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:10px;margin-bottom:1rem"><div style="background:${p.colour};border:1px solid rgba(255,255,255,.1);border-left:4px solid var(--brass);border-radius:3px;padding:1rem"><div style="font-family:'Oswald',sans-serif;font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--brass2);margin-bottom:.35rem">${p.year}</div><div style="font-family:'Special Elite',cursive;font-size:1.15rem;color:#fff;margin-bottom:.35rem">${p.title}</div><div style="font-size:14px;color:rgba(255,255,255,.75);line-height:1.65">${p.text}</div></div><div style="background:rgba(21,39,68,.74);border:1px solid rgba(255,255,255,.1);border-radius:3px;padding:1rem"><div style="font-family:'Oswald',sans-serif;font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--brass2);margin-bottom:.35rem">Role focus</div><div style="font-size:15px;color:rgba(255,255,255,.82);line-height:1.65">${p.role}</div><div style="margin-top:.8rem;font-size:13px;color:rgba(255,255,255,.55);line-height:1.55">Use the timeline as a modelling selector: the same Beaufighter airframe can require very different aerials, stores, markings and weathering depending on date and theatre.</div></div></div>`;const grid=document.getElementById('tl-sqns');if(grid)grid.innerHTML=SQ.map(s=>`<div class="tl-sqn" style="border-left-color:${GROUP_COLOURS[s.group]||'var(--brass)'}"><div class="tl-sqn-num">No.${s.num} Sqn</div><div class="tl-sqn-status">${s.base}</div><div style="font-family:'Oswald',sans-serif;font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:${GROUP_COLOURS[s.group]||'var(--brass2)'};margin-top:2px">${mapGroupLabel(s.group)}</div></div>`).join('');}
function renderSurvivors(){const el=document.getElementById('survivors-grid');if(!el)return;el.innerHTML=`<div class="survivor-grid">${BEAU_SURVIVORS.map(s=>`<div class="survivor-card"><div class="survivor-hd"><div><div class="survivor-serial">${s.serial}</div><div class="survivor-name">${s.name}</div></div><span class="survivor-status status-${s.status}">${s.status==='restore'?'🔧 Restoring':s.status==='fly'?'✈ Flying':'🏛 Static'}</span></div><div class="survivor-body"><div class="survivor-row"><span class="survivor-key">Location</span><span>${s.location}</span></div><div class="survivor-row"><span class="survivor-key">Variant</span><span>${s.variant}</span></div><div class="survivor-row"><span class="survivor-key">Markings</span><span>${s.markings}</span></div><div class="survivor-row"><span class="survivor-key">History</span><span>${s.history}</span></div><div style="margin-top:.6rem;font-size:12px;color:var(--brass2);font-style:italic;border-top:1px solid rgba(255,255,255,.06);padding-top:.5rem;line-height:1.55">${s.note}</div><a href="${s.link}" target="_blank" rel="noopener" class="shop-btn hb-raf" style="margin-top:.75rem;font-size:12px">Open reference page ↗</a></div></div>`).join('')}</div>`;}
function renderBooks(){const el=document.getElementById('books-grid');if(!el)return;el.innerHTML=Object.entries(BEAU_BOOKS).map(([cat,books])=>`<div class="books-section"><div class="books-section-title">${cat}</div><div class="books-grid">${books.map(b=>`<div class="book-card"><div class="book-spine" style="background:${b.colour}"></div><div class="book-info"><div class="book-title">${b.title}</div><div class="book-author">${b.author} · ${b.year}</div><div class="book-rating">${'★'.repeat(b.stars)}${'☆'.repeat(5-b.stars)}</div><div class="book-desc">${b.desc}</div><div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:.4rem">${(b.shops||[]).map(x=>`<a class="shop-btn hb-gold" href="${x.url}" target="_blank" style="font-size:12px;padding:4px 10px" rel="noopener">${x.label} ↗</a>`).join('')}</div></div></div>`).join('')}</div></div>`).join('');}
