function renderMedia(){const el=document.getElementById('media-grid');if(!el)return;el.dataset.rendered='1';const groups=[['video','Videos'],['archive','Archives and museum pages'],['photo','Photo/reference routes']];el.innerHTML=groups.map(([k,label])=>`<div class="section-label">${label}</div><div class="wa-ref-strip">${BEAU_MEDIA.filter(i=>i.type===k).map(beauThumbCard).join('')}</div>`).join('');}


/* Beaufighter-specific real theatre map override: uses real lat/lon data, not Spitfire UK group geometry. */
function renderMap(){
  const mapEl=document.getElementById('leaflet-map');
  if(!mapEl) return;
  if(mapRendered){ setTimeout(()=>leafletMap && leafletMap.invalidateSize(),80); return; }
  if(typeof L==='undefined'){
    mapEl.innerHTML = `<div style="padding:2rem;color:rgba(255,255,255,.65);font-family:'Oswald',sans-serif;letter-spacing:.08em;text-transform:uppercase">Map library loading…</div>`;
    setTimeout(renderMap,250); return;
  }
  mapRendered=true;
  leafletMap = L.map('leaflet-map',{zoomControl:true,attributionControl:true,scrollWheelZoom:false,worldCopyJump:false}).setView([32,20],3);
  L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png',{attribution:'&copy; OpenStreetMap &copy; CARTO',subdomains:'abcd',maxZoom:10,minZoom:2}).addTo(leafletMap);
  leafletMarkers={};
  STATIONS.forEach(st=>{
    const lat=Number(st.lat), lng=Number(st.lon);
    st._lat=lat; st._lng=lng;
    const col=GROUP_COLOURS[st.group]||'#999';
    const icon=L.divIcon({className:'',html:`<div class="raf-leaflet-marker" data-id="${st.id}" style="background:${col}"></div>`,iconSize:[18,18],iconAnchor:[9,9]});
    const marker=L.marker([lat,lng],{icon}).addTo(leafletMap);
    marker._rafStation=st;
    marker.on('click',()=>showMapStation(st));
    marker.bindTooltip(`<span class="raf-leaflet-label">${st.name}</span>`,{permanent:false,direction:'top',offset:[0,-10],opacity:.96,className:''});
    leafletMarkers[st.id]=marker;
  });
  const bounds=L.latLngBounds(STATIONS.map(st=>[st._lat,st._lng]));
  leafletMap.fitBounds(bounds.pad(.20),{padding:[18,18],maxZoom:5});
  setTimeout(()=>leafletMap.invalidateSize(),100);
  showMapIntro();
}

function filterMapGroup(group,btn){
  renderMap();
  document.querySelectorAll('.map-filter-btn').forEach(b=>b.classList.remove('on'));
  if(btn) btn.classList.add('on');
  Object.values(leafletMarkers||{}).forEach(marker=>{
    const st=marker._rafStation;
    const show=group==='all'||st.group===group;
    if(show){ if(leafletMap&&!leafletMap.hasLayer(marker)) marker.addTo(leafletMap); }
    else { if(leafletMap&&leafletMap.hasLayer(marker)) leafletMap.removeLayer(marker); }
  });
  const shown=STATIONS.filter(st=>group==='all'||st.group===group);
  if(leafletMap&&shown.length){ leafletMap.fitBounds(L.latLngBounds(shown.map(st=>[st._lat,st._lng])).pad(.30),{padding:[18,18],maxZoom: group==='all'?5:7}); }
  const box=document.getElementById('map-sqn-list');
  if(box){
    box.innerHTML=`<div style="font-family:'Special Elite',cursive;font-size:1.18rem;color:#fff;margin-bottom:.35rem">${group==='all'?'All Beaufighter theatres':mapGroupLabel(group)}</div>
    <div style="font-family:'Oswald',sans-serif;font-size:11px;letter-spacing:.13em;text-transform:uppercase;color:var(--brass2);margin-bottom:.75rem">${shown.length} marker${shown.length===1?'':'s'} shown</div>
    <p style="font-size:14px;color:rgba(255,255,255,.68);line-height:1.65">Click a base or theatre marker to open the Beaufighter unit links, role notes and modelling cues. This map covers UK night defence, Coastal Command, Mediterranean/desert and Far East/RAAF contexts.</p>
    <div style="max-height:260px;overflow:auto;padding-right:.2rem;margin-top:.7rem">${shown.map(st=>`<div class="map-sqn-chip" onclick="showMapStation('${st.id}')" style="margin-top:.45rem;cursor:pointer"><b>${st.name}</b><div style="font-size:11px;color:rgba(255,255,255,.65)">${(st.sqns||[]).join(' · ')} · ${mapGroupLabel(st.group)}</div></div>`).join('')}</div>`;
  }
}

document.addEventListener('DOMContentLoaded',function(){const sl=document.getElementById('tl-slider');if(sl){sl.max=BEAU_PHASES.length-1;sl.value=0;}updateTimeline(0);});
